<?php require_once __DIR__ . '/../auth/guard.php'; requireRole('teacher'); ?>
<div class="admin-topbar"><div><h1>My Classes &amp; Sections</h1><p>Enroll students in your classes or transfer them between your sections.</p></div></div>
<div id="teacherClassNotice" class="alert d-none" role="status"></div>
<div class="admin-card mb-4"><h2 class="h5 fw-bold">Add / Transfer Student</h2><form id="teacherEnrollForm" class="row g-2">
<div class="col-md-5"><label class="form-label">Student</label><select class="admin-select w-100" id="teacherEnrollStudent" name="student_id" required><option value="">Loading students…</option></select></div>
<div class="col-md-5"><label class="form-label">My class</label><select class="admin-select w-100" id="teacherEnrollClass" name="class_id" required><option value="">Loading classes…</option></select></div>
<div class="col-md-2 d-flex align-items-end"><button class="admin-btn admin-btn-primary w-100" type="submit">Enroll student</button></div>
<div class="col-12"><label><input type="checkbox" id="teacherTransferMode"> Transfer student from previous active class (deactivate old enrollment)</label></div>
</form></div>
<div class="admin-card"><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Class / Section</th><th>Grade</th><th>School year</th><th>Active students</th><th>Status</th><th>Roster</th></tr></thead><tbody id="teacherClassRows"><tr><td colspan="6">Loading classes…</td></tr></tbody></table></div></div>
<div class="admin-card mt-4" id="teacherRosterPanel" hidden><div class="d-flex justify-content-between align-items-start gap-3 mb-3"><div><h2 class="h5 fw-bold mb-1" id="teacherRosterTitle">Class roster</h2><p class="text-muted mb-0" id="teacherRosterMeta"></p></div><button type="button" class="admin-btn admin-btn-light" id="teacherRosterClose">Close roster</button></div><div class="admin-toolbar"><input id="teacherRosterSearch" class="admin-input" type="search" placeholder="Search student name or number…" style="flex:1;min-width:220px"><button type="button" class="admin-btn admin-btn-light" id="teacherRosterPrint"><i class="bi bi-printer"></i> Print roster</button></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>#</th><th>Student name</th><th>Student number</th><th>Enrolled</th></tr></thead><tbody id="teacherRosterRows"></tbody></table></div></div>
<script>
(function(){const ep='api/system_management.php',rosterPanel=document.getElementById('teacherRosterPanel'),rosterRows=document.getElementById('teacherRosterRows'),rosterSearch=document.getElementById('teacherRosterSearch'),form=document.getElementById('teacherEnrollForm'),rows=document.getElementById('teacherClassRows'),student=document.getElementById('teacherEnrollStudent'),cls=document.getElementById('teacherEnrollClass'),notice=document.getElementById('teacherClassNotice');if(!form||form.dataset.bound)return;form.dataset.bound='1';const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function msg(t,ok){notice.className='alert '+(ok?'alert-success':'alert-danger');notice.textContent=t}
async function load(){try{const r=await fetch(ep+'?view=classes',{credentials:'same-origin'}),d=await r.json();if(!r.ok||!d.success)throw Error(d.message);student.innerHTML='<option value="">Select student</option>'+(d.students||[]).map(s=>'<option value="'+s.student_id+'">'+esc(s.full_name+(s.student_number?' · '+s.student_number:''))+'</option>').join('');cls.innerHTML='<option value="">Select your class</option>'+(d.classes||[]).filter(c=>c.status==='active').map(c=>'<option value="'+c.class_id+'">'+esc(c.class_name+(c.section?' - '+c.section:'')+' ('+c.school_year+')')+'</option>').join('');rows.innerHTML=d.classes.length?d.classes.map(c=>'<tr><td><strong>'+esc(c.class_name+(c.section?' - '+c.section:''))+'</strong></td><td>'+esc(c.grade_level||'—')+'</td><td>'+esc(c.school_year)+'</td><td>'+Number(c.student_count)+'</td><td>'+esc(c.status)+'</td><td><button type="button" class="admin-btn admin-btn-light" data-roster="'+Number(c.class_id)+'" data-class-name="'+esc(c.class_name+(c.section?' - '+c.section:''))+'">View roster</button></td></tr>').join(''):'<tr><td colspan="6" class="text-center text-muted">No classes are assigned to your account. Ask an administrator to assign a class.</td></tr>'}catch(e){msg(e.message,false);rows.innerHTML='<tr><td colspan="6">'+esc(e.message)+'</td></tr>'}}
let rosterStudents=[];
function renderRoster(){const term=(rosterSearch.value||'').toLowerCase();const filtered=rosterStudents.filter(s=>[s.student_name,s.student_number].join(' ').toLowerCase().includes(term));rosterRows.innerHTML=filtered.length?filtered.map((s,i)=>'<tr><td>'+String(i+1)+'</td><td>'+esc(s.student_name)+'</td><td>'+esc(s.student_number||'—')+'</td><td>'+esc(s.enrolled_at||'—')+'</td></tr>').join(''):'<tr><td colspan="4" class="text-center text-muted py-3">No active students found in this class.</td></tr>'}
rows.addEventListener('click',async e=>{const b=e.target.closest('[data-roster]');if(!b)return;try{const r=await fetch(ep+'?view=class_roster&class_id='+encodeURIComponent(b.dataset.roster),{credentials:'same-origin'}),d=await r.json();if(!r.ok||!d.success)throw Error(d.message||'Unable to load class roster.');rosterStudents=d.students||[];document.getElementById('teacherRosterTitle').textContent='Roster: '+(d.class.class_name+(d.class.section?' - '+d.class.section:''));document.getElementById('teacherRosterMeta').textContent='Grade: '+(d.class.grade_level||'—')+' · School year: '+d.class.school_year+' · Active students: '+rosterStudents.length;rosterSearch.value='';renderRoster();rosterPanel.hidden=false;rosterPanel.scrollIntoView({behavior:'smooth',block:'start'})}catch(err){msg(err.message,false)}});
rosterSearch.addEventListener('input',renderRoster);
document.getElementById('teacherRosterClose').addEventListener('click',()=>{rosterPanel.hidden=true});
document.getElementById('teacherRosterPrint').addEventListener('click',()=>{const w=window.open('','_blank','width=900,height=700');if(!w){msg('Please allow pop-ups to print the roster.',false);return;}const title=esc(document.getElementById('teacherRosterTitle').textContent),meta=esc(document.getElementById('teacherRosterMeta').textContent);w.document.write('<!doctype html><html><head><title>'+title+'</title><style>body{font:14px Arial,sans-serif;padding:24px}h1{font-size:22px}table{width:100%;border-collapse:collapse;margin-top:18px}th,td{border:1px solid #bbb;padding:8px;text-align:left}th{background:#f2f2f2}</style></head><body><h1>'+title+'</h1><p>'+meta+'</p><table><thead><tr><th>#</th><th>Student name</th><th>Student number</th><th>Enrolled</th></tr></thead><tbody>'+rosterRows.innerHTML+'</tbody></table></body></html>');w.document.close();w.focus();w.print();});
form.addEventListener('submit',async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(form));body.action=document.getElementById('teacherTransferMode').checked?'class_transfer':'class_enroll';try{const r=await fetch(ep,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(!r.ok||!d.success)throw Error(d.message);msg(d.message,true);form.reset();await load()}catch(e){msg(e.message,false)}});load()})();
</script>